
create view [Staging].[vw_Datapay_cost_structures]
as 
select
	 src.[company_id] 	,src.[type] 	,src.[cost_box_id] 	,src.[cost_box_parent_id] 	,src.[code] 	,src.[name] 	,src.[inactive] 	,src.[level0_cost_box_id] 	,src.[level0_parent_costbox_id] 	,src.[level0_code] 	,src.[level0_name] 	,src.[level0_inactive] 	,src.[level1_cost_box_id] 	,src.[level1_parent_costbox_id] 	,src.[level1_code] 	,src.[level1_name] 	,src.[level1_inactive] 	,src.[level2_cost_box_id] 	,src.[level2_parent_costbox_id] 	,src.[level2_code] 	,src.[level2_name] 	,src.[level2_inactive] 	,src.[level3_cost_box_id] 	,src.[level3_parent_costbox_id] 	,src.[level3_code] 	,src.[level3_name] 	,src.[level3_inactive] 
from [Landing].[Datapay_cost_structures] as src;